<?php
require __DIR__.'/../app/bootstrap.php'; require_role(['admin']);
$q=trim((string)($_GET['q']??''));$page=max(1,(int)($_GET['page']??1));$per=30;$where='';$args=[];if($q!==''){$where='WHERE l.action LIKE ? OR l.entity_type LIKE ? OR l.entity_id LIKE ? OR u.username LIKE ? OR u.full_name LIKE ?';$like='%'.$q.'%';$args=[$like,$like,$like,$like,$like];}$st=db()->prepare("SELECT l.*,u.username,u.full_name FROM audit_logs l LEFT JOIN users u ON u.id=l.user_id {$where} ORDER BY l.id DESC LIMIT {$per} OFFSET ".(($page-1)*$per));$st->execute($args);$logs=$st->fetchAll();
